/* LK compiles this loop inline inside lcm_init/lcm_suspend; argument order and
 * the "table[i].count is the delay in ms for REGFLAG_DELAY" convention are
 * taken from the disassembly. */
static void push_table(struct LCM_setting_table *table, unsigned int count)
{
	unsigned int i;

	for (i = 0; i < count; i++) {
		unsigned int cmd = table[i].cmd;

		switch (cmd) {
		case REGFLAG_DELAY:
			MDELAY(table[i].count);
			break;
		case REGFLAG_END_OF_TABLE:
			break;
		default:
			dsi_set_cmdq_V2(cmd, table[i].count, table[i].para_list, 1);
			break;
		}
	}
}

static void lcm_set_util_funcs(const LCM_UTIL_FUNCS *util)
{
	/* LK: memcpy(&lcm_util, util, 0x74) == sizeof(LCM_UTIL_FUNCS) */
	memcpy(&lcm_util, util, sizeof(LCM_UTIL_FUNCS));
}

