	params->width  = FRAME_WIDTH;
	params->height = FRAME_HEIGHT;

	params->dbi.te_mode         = LCM_DBI_TE_MODE_VSYNC_ONLY;  /* +0x5C = 1 */
	params->dbi.te_edge_polarity = LCM_POLARITY_RISING;        /* +0x60 = 0 */

	params->dsi.mode                = SYNC_PULSE_VDO_MODE;     /* +0x16C = 1 */
	params->dsi.LANE_NUM            = LCM_THREE_LANE;          /* +0x180 = 3 */
	params->dsi.data_format.color_order = LCM_COLOR_ORDER_RGB; /* +0x184 = 0 */
	params->dsi.data_format.trans_seq   = LCM_DSI_TRANS_SEQ_MSB_FIRST; /* 0x188 = 0 */
	params->dsi.data_format.padding     = LCM_DSI_PADDING_ON_LSB;      /* 0x18C = 0 */
	params->dsi.data_format.format      = LCM_DSI_FORMAT_RGB888;       /* 0x190 = 2 */
	params->dsi.intermediat_buffer_num  = 0;                   /* +0x194 = 0 */
	params->dsi.PS                      = LCM_PACKED_PS_24BIT_RGB888;  /* 0x198 = 2 */
	params->dsi.word_count              = 1440;                /* +0x19C = 0x5A0 */
	params->dsi.packet_size             = 256;                 /* +0x1A0 = 0x100 */

	params->dsi.vertical_sync_active   = 4;                    /* +0x1A8 */
	params->dsi.vertical_backporch     = 15;                   /* +0x1AC */
	params->dsi.vertical_frontporch    = 18;                   /* +0x1B0 */
