/* ------------------------------------------------------------------ */
/* lcm_init - exact recovered sequence                                */
/* ------------------------------------------------------------------ */

static void lcm_init(void)
{
	SET_RESET_PIN(1);
	MDELAY(10);
	SET_RESET_PIN(0);
	MDELAY(20);          /* LK 0x81E20A70 `movs r0,#0x14`; kernel uses 15 ms */
	SET_RESET_PIN(1);
	MDELAY(120);         /* LK 0x81E20A80 `movs r0,#0x78` */

	push_table(lcm_init_setting,
		   sizeof(lcm_init_setting) / sizeof(struct LCM_setting_table));
}

static void lcm_suspend(void)
{
	unsigned int array[1];

	push_table(lcm_suspend_setting,
		   sizeof(lcm_suspend_setting) / sizeof(struct LCM_setting_table));

	SET_RESET_PIN(1);
	MDELAY(10);
	SET_RESET_PIN(0);
	MDELAY(20);
	SET_RESET_PIN(0);
	MDELAY(120);
}

static void lcm_resume(void)
{
	lcm_init();          /* LK: `b.w lcm_init` - a plain tail branch */
}

/* ------------------------------------------------------------------ */
/* lcm_compare_id - reads RDDID and compares against 0x9504           */
/* ------------------------------------------------------------------ */

static unsigned int lcm_compare_id(void)
{
	unsigned char  buffer[4];
	unsigned int   array[1];
	unsigned int   id;

	SET_RESET_PIN(1);
	MDELAY(10);
	SET_RESET_PIN(0);
	MDELAY(10);
	SET_RESET_PIN(1);
	MDELAY(120);

	/* LK 0x81E208F4: movw r3,#0x3700 / movt r3,#3  ->  0x00033700
	 * Semantic: DCS SET_MAX_RETURN_PKT_SIZE (0x37) with one parameter (0x03),
	 * required before the 3-byte RDDID read below.  The literal is kept
	 * verbatim because the packed-word byte order of dsi_set_cmdq is a
	 * board/API convention; dsi_set_cmdq_V2(0x37, 1, {3}, 1) is the
	 * unambiguous equivalent if the local cmdq packing differs. */
	array[0] = 0x00033700;
	dsi_set_cmdq(array, 1, 1);

	read_reg_v2(0x04, buffer, 3);           /* RDDID */

	id = (buffer[1] << 8) | buffer[2];      /* LK: orr r4,r1,r3,lsl #8 */

	return (LCM_ID == id) ? TRUE : FALSE;   /* LK: clz/subs -> 0x9504 compare */
}


